#include <torch/extension.h>
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
  m.def("top_k_per_row_prefill", &top_k_per_row_prefill, "vLLM top_k_per_row_prefill (CUDA)");
  m.def("top_k_per_row_decode", &top_k_per_row_decode, "vLLM top_k_per_row_decode (CUDA)");
  m.def("persistent_topk", &persistent_topk, "vLLM persistent_topk (CUDA)");
  m.def("cooperative_topk", &cooperative_topk, "vLLM cooperative_topk (CUDA)");
}

